import React, { useCallback, useEffect, useState } from 'react';
import { faSearch } from '@fortawesome/free-solid-svg-icons';
import { graphql } from 'gatsby';
import Layout from '../components/layout';
import Seo from '../components/seo';
import PostItem from '../components/post-item';
import {
 SearchInputForm,
 SearchIcon,
 Tag,
 PostListWrapper,
 CenterPos,
 MainContainer,
 SideContainer,
 PostListContainer,
 Profile,
 Name,
 ProfileEmoji,
 MobileContainer,
 MobileEmoji,
 MobileName,
 MobileProfile,
 CategoryTitle,
 RightSideContainer,
 TagList,
} from '../style/blogMainStyle';

// const ALL_NAME = 'ALL';

const BlogIndex = ({ data, location }) => {
 const siteTitle = data.site.siteMetadata?.title || 'Title';
 const allPosts = data.allMarkdownRemark.nodes;
 //  const categories = [{ fieldValue: ALL_NAME, totalCount: allPosts.length }, ...data.categories.group];
 const tags = data.tags.group;
 const [posts, setPosts] = useState([...allPosts]);
 const [keyword, setKeyword] = useState('');
 const [selectedTag, setSelectedTag] = useState({ fieldValue: 'All', totalCount: allPosts.length });

 const onChangeKeyword = useCallback((e) => {
  setKeyword(e.target.value);
 }, []);

 const filterPosts = useCallback(
  (tag) => {
   const filteredPosts = allPosts.filter((post) => {
    if (tag.fieldValue === 'All') {
     return true;
    }
    return post.frontmatter.tags.includes(tag.fieldValue);
   });
   setPosts([...filteredPosts]);
  },
  [selectedTag],
 );

 const searchProc = useCallback(
  (e) => {
   e.preventDefault();
   setSelectedTag({ fieldValue: 'All', totalCount: allPosts.length });
   if (!keyword || !keyword.trim()) {
    setPosts([...allPosts]);
    return;
   }
   setPosts([
    ...allPosts.filter((post) => {
     if (post.frontmatter.title?.includes(keyword) || post.frontmatter.description?.includes(keyword)) {
      return true;
     }
    }),
   ]);
  },
  [keyword],
 );

 return (
  <Layout location={location} title={siteTitle}>
   <MainContainer>
    <SideContainer>
     <Profile>
      <ProfileEmoji>🥳</ProfileEmoji>
      <Name>
       heeyoung<div>Frontend Engiener</div>
      </Name>
      <div>✨ 주로 리액트와 자바 스크립트, 타입 스크립트를 다룹니다.</div>
     </Profile>
    </SideContainer>
    <MobileContainer>
     <MobileProfile>
      <MobileEmoji>🥳</MobileEmoji>
      <MobileName>
       heeyoung<div>Frontend Engiener</div>
       <div>✨ 주로 리액트와 자바 스크립트, 타입 스크립트를 다룹니다.</div>
      </MobileName>
     </MobileProfile>
    </MobileContainer>
    <RightSideContainer>
     <h5>Tags 🏷️</h5>
     <TagList>
      <Tag
       onClick={() => {
        setSelectedTag({ fieldValue: 'All', totalCount: allPosts.length });
        filterPosts({ fieldValue: 'All', totalCount: allPosts.length });
       }}
      >
       All ({allPosts.length})
      </Tag>
      {tags.map((tag) => {
       return (
        <Tag
         key={tag.fieldValue}
         isSelected={selectedTag.fieldValue === tag.fieldValue}
         onClick={() => {
          setSelectedTag({ fieldValue: tag.fieldValue, totalCount: tag.totalCount });
          filterPosts({ fieldValue: tag.fieldValue, totalCount: tag.totalCount });
          window.scrollTo(0, 0);
         }}
        >
         {tag.fieldValue} ({tag.totalCount})
        </Tag>
       );
      })}
     </TagList>
    </RightSideContainer>
    <PostListContainer>
     <SearchInputForm onSubmit={searchProc}>
      <input type="text" value={keyword} onChange={onChangeKeyword} placeholder="Search..." />
      <SearchIcon>🔎</SearchIcon>
     </SearchInputForm>
     <CategoryTitle>
      {selectedTag.fieldValue}
      <div>{selectedTag.totalCount} 개의 글</div>
     </CategoryTitle>
     <PostListWrapper style={{ listStyle: 'none' }}>
      {posts.length === 0 && <CenterPos>포스트가 존재하지 않습니다.</CenterPos>}
      {posts.map((post) => {
       const title = post.frontmatter.title || post.fields.slug;
       return <PostItem key={post.fields.slug} title={title} post={post} />;
      })}
     </PostListWrapper>
    </PostListContainer>
   </MainContainer>
  </Layout>
 );
};

export default BlogIndex;

/**
 * Head export to define metadata for the page
 *
 * See: https://www.gatsbyjs.com/docs/reference/built-in-components/gatsby-head/
 */
export const Head = () => <Seo title="klloo" />;

export const pageQuery = graphql`
 {
  site {
   siteMetadata {
    title
   }
  }
  allMarkdownRemark(sort: { frontmatter: { date: DESC } }) {
   nodes {
    excerpt(pruneLength: 200, truncate: true)
    fields {
     slug
    }
    frontmatter {
     date(formatString: "MMMM DD, YYYY")
     title
     description
     category
     icon
     tags
    }
   }
  }
  categories: allMarkdownRemark(limit: 2000) {
   group(field: frontmatter___category) {
    fieldValue
    totalCount
   }
  }
  tags: allMarkdownRemark(limit: 2000) {
   group(field: frontmatter___tags) {
    fieldValue
    totalCount
   }
  }
 }
`;
